plosion", "data": {"color01": "#FFFFFF", "color02": "#FFFFFF", "spritePath": "modules/levels-3d-preview/assets/particles/dust.png"}, "sound": {"enable": false}, "secondary": {"enable": false, "data": {"color01": "#FFFFFF", "color02": "#FFFFFF", "spritePath": "modules/levels-3d-preview/assets/particles/dust.png"}}}}}, "effects": [], "folder": null};
  const LEAP_ITEM = {"name": "大跳 Super Leap", "type": "consumable", "img": "icons/magic/control/buff-flight-wings-blue.webp", "system": {"description": {"value": "<p>从问号砖中获得的一次大跳。用一个<strong>附赠动作</strong>触发，选择 30 尺内一处落点，腾空跃至该处；这次移动<strong>不引发借机攻击</strong>。若你下次短休前未使用，它便会消散。</p>", "chat": ""}, "type": {"value": "", "subtype": ""}, "quantity": 1, "weight": {"value": 0, "units": "lb"}, "price": {"value": 0, "denomination": "gp"}, "uses": {"max": "1", "spent": 0, "recovery": [], "autoDestroy": true}, "activities": {"dnd5eactivity000": {"_id": "dnd5eactivity000", "type": "utility", "name": "大跳", "activation": {"type": "bonus", "value": 1, "override": false}, "consumption": {"targets": [{"type": "itemUses", "value": "1"}], "scaling": {"allowed": false}, "spellSlot": false}, "duration": {"units": "inst", "concentration": false, "override": false}, "range": {"units": "self", "override": false}, "target": {"affects": {"type": "self", "count": "", "choice": false, "special": ""}, "override": false}}}, "source": {"rules": "2014", "revision": 1}, "identifier": "-super-leap"}, "effects": [], "flags": {"world": {"qblockTemp": true}, "midiProperties": {"confirmTargets": "default", "autoTargetType": "any"}, "midi-qol": {"onUseMacroName": "[postActiveEffects]ItemMacro"}, "dae": {"macro": {"name": "大跳 Super Leap", "img": "icons/magic/control/buff-flight-wings-blue.webp", "type": "script", "scope": "global", "command": "(async () => {\n  const me = canvas.tokens.controlled[0] ?? (typeof token !== \"undefined\" ? token : null);\n  if (!me) { ui.notifications.warn(\"请先选中你的 Token 再大跳\"); return; }\n  const gridSize = canvas.grid.size;\n  const ftPerSq = canvas.scene.grid?.distance ?? 5;\n  const SNAP = CONST.GRID_SNAPPING_MODES;\n  const RANGE_FT = 30;\n  const TIMEOUT_MS = 20000;\n  const cc = { x: me.center?.x ?? (me.x + me.w / 2), y: me.center?.y ?? (me.y + me.h / 2) };\n  const ftBetween = (p, q) => Math.hypot(p.x - q.x, p.y - q.y) / gridSize * ftPerSq;\n  const snapC = (p) => { try { return canvas.grid.getSnappedPoint({ x: p.x, y: p.y }, { mode: SNAP.CENTER, resolution: 1 }); } catch (e) { return { x: Math.round(p.x / gridSize) * gridSize, y: Math.round(p.y / gridSize) * gridSize }; } };\n\n  const pick = () => new Promise((resolve) => {\n    const maxSq = Math.max(1, Math.floor(RANGE_FT / ftPerSq));\n    const g = new PIXI.Graphics();\n    g.lineStyle(2, 0x66ff66, 0.9); g.beginFill(0x66ff66, 0.05);\n    g.drawCircle(cc.x, cc.y, maxSq * gridSize); g.endFill();\n    g.zIndex = 10000; canvas.app.stage.addChild(g);\n    ui.notifications.info(\"点击落点进行大跳（不超过 \" + RANGE_FT + \" 尺）\");\n    const cleanup = () => { try { canvas.app.stage.off(\"pointerdown\", h); } catch (e) {} try { canvas.app.stage.removeChild(g); } catch (e) {} };\n    const h = (ev) => { cleanup(); let p = null; try { p = ev.data.getLocalPosition(canvas.app.stage); } catch (e) {} resolve(p ? snapC(p) : null); };\n    canvas.app.stage.on(\"pointerdown\", h);\n    setTimeout(() => { cleanup(); resolve(null); }, TIMEOUT_MS);\n  });\n\n  const dest = await pick();\n  if (!dest) { ui.notifications.warn(\"已取消大跳\"); return; }\n  if (ftBetween(dest, cc) > RANGE_FT + 0.001) { ui.notifications.warn(\"超出 \" + RANGE_FT + \" 尺，已取消\"); return; }\n\n  // 尘土冲击：在候选 key 里挑一个库里存在的播，找不到就静默跳过（不报错）\n  try {\n    const cands = [\"jb2a.impact.ground_crack.orange.01\", \"jb2a.smoke.puff.centered.grey.1\", \"jb2a.impact.011.orange\", \"jb2a.smoke.puff.ring.01.white\", \"jb2a.dust_cloud.01\"];\n    let fx = null;\n    for (const k of cands) { try { if (Sequencer?.Database?.entryExists?.(k)) { fx = k; break; } } catch (e) {} }\n    if (fx && typeof Sequence !== \"undefined\") {\n      new Sequence()\n        .effect().file(fx).atLocation({ x: cc.x, y: cc.y }).scaleToObject(1.5)\n        .effect().file(fx).atLocation({ x: dest.x, y: dest.y }).scaleToObject(2).delay(200)\n        .play();\n    }\n  } catch (e) { console.error(\"大跳 | 动画失败\", e); }\n\n  // 传送式移动（不引发借机攻击）\n  try {\n    if (typeof MidiQOL?.moveToken === \"function\") await MidiQOL.moveToken(me, { x: dest.x, y: dest.y }, false);\n    else await me.document.update({ x: dest.x - gridSize / 2, y: dest.y - gridSize / 2 });\n  } catch (e) { console.error(\"大跳 | 移动失败\", e); }\n\n  ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: me.actor }), content: \"<p>🦘 <strong>超级跳</strong>：\" + me.name + \" 腾空大跳、稳稳落地，期间不引发借机攻击。</p>\" });\n})();\n", "author": "", "ownership": {"default": 3}, "_id": null, "folder": null, "sort": 0, "flags": {}}}}};

  const chat = (html) => ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: a }), content: html });
  const rollShow = async (formula, flavor) => {
    const r = new Roll(formula); await r.evaluate();
    await r.toMessage({ flavor, speaker: ChatMessage.getSpeaker({ actor: a }) });
    return r.total;
  };

  // —— 短休清理钩子：首次运行自注册（会话级，无需世界脚本）——
  if (!globalThis.__qblockRestHook) {
    globalThis.__qblockRestHook = Hooks.on("dnd5e.restCompleted", async (restActor) => {
      try {
        const ids = restActor.items.filter((i) => i.getFlag("world", TEMP_FLAG)).map((i) => i.id);
        if (ids.length) {
          await restActor.deleteEmbeddedDocuments("Item", ids);
          ChatMessage.create({ speaker: ChatMessage.getSpeaker({ actor: restActor }), content: "<p>问号砖吐出的限时道具随短休消散了。</p>" });
        }
      } catch (e) { console.error("问号砖 | 短休清理失败", e); }
    });
  }

  const grant = async (data) => { await a.createEmbeddedDocuments("Item", [foundry.utils.deepClone(data)]); };

  // —— 无敌星：抗性一切伤害 + ATL 发光（效应结束自动熄灭）——
  const DMG = ["acid","bludgeoning","cold","fire","force","lightning","necrotic","piercing","poison","psychic","radiant","slashing","thunder"];
  const starEffect = () => ({
    name: "无敌星 Invincibility Star",
    img: "icons/magic/control/buff-flight-wings-runes-blue.webp",
    description: "<p>你周身闪耀星光，到你下回合结束前对一切伤害具有抗性（伤害减半），并散发光芒。</p>",
    duration: { seconds: 6 }, statuses: [], origin: "", transfer: false, disabled: false,
    changes: [
      { key: "system.traits.dr.value", mode: 2, value: "acid", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "bludgeoning", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "cold", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "fire", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "force", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "lightning", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "necrotic", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "piercing", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "poison", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "psychic", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "radiant", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "slashing", priority: 20 },
      { key: "system.traits.dr.value", mode: 2, value: "thunder", priority: 20 },
      { key: "ATL.light.dim", mode: 5, value: "20", priority: 20 },
      { key: "ATL.light.bright", mode: 5, value: "10", priority: 20 },
      { key: "ATL.light.color", mode: 5, value: "#ffd700", priority: 20 },
      { key: "ATL.light.alpha", mode: 5, value: "0.45", priority: 20 },
      { key: "ATL.light.animation", mode: 5, value: '{"type":"pulse","speed":5,"intensity":5}', priority: 20 },
    ],
    flags: {},
  });
  const dropStar = async () => {
    const old = a.effects.filter((e) => e.name?.includes("无敌星")).map((e) => e.id);
    if (old.length) await a.deleteEmbeddedDocuments("ActiveEffect", old);
    await a.createEmbeddedDocuments("ActiveEffect", [starEffect()]);
    try {
      const cands = ["jb2a.twinkling_stars.points.many.purple", "jb2a.twinkling_stars.points.many.blue", "jb2a.twinkling_stars.points.four.purple"];
      let fx = null;
      for (const k of cands) { try { if (Sequencer?.Database?.entryExists?.(k)) { fx = k; break; } } catch (e) {} }
      if (fx && typeof Sequence !== "undefined") new Sequence().effect().file(fx).attachTo(me).scaleToObject(2.2).persist().duration(6000).fadeOut(500).name("qblock-star-" + me.id).play();
    } catch (e) {}
  };

  // —— 掷 1d6 决定产物 ——
  const d6 = await rollShow("1d6", "🟨 问号砖 d6");
  let line = "";
  if (d6 === 1) {
    const t = await rollShow("2d4+10", "🛡 临时生命");
    if (typeof a.applyTempHP === "function") await a.applyTempHP(t);
    else await a.update({ "system.attributes.hp.temp": Math.max(a.system.attributes?.hp?.temp || 0, t) });
    line = "<strong>① 临时生命</strong>：获得 " + t + " 点临时生命值（到短休为止）。";
  } else if (d6 === 2) {
    await grant(FIRE_SPARK);
    line = "<strong>② 火花</strong>：一枚可投掷的火花进了你的背包（3d6 火焰·远程攻击命中）。";
  } else if (d6 === 3) {
    await grant(MUSHROOM);
    line = "<strong>③ 蘑菇</strong>：一颗蘑菇进了你的背包（回 2d6，可给自己或相邻队友）。";
  } else if (d6 === 4) {
    const gp = (a.system.currency?.gp ?? 0) + 10;
    await a.update({ "system.currency.gp": gp });
    line = "<strong>④ 金币</strong>：叮！获得 10 枚金币（+10 gp）。";
  } else if (d6 === 5) {
    await dropStar();
    line = "<strong>⑤ 无敌星</strong>：到你下回合结束前抗性一切伤害并发光。";
  } else {
    await grant(LEAP_ITEM);
    line = "<strong>⑥ 超级跳</strong>：一枚『大跳』进了你的背包——附赠动作触发，点地大跳、不引发借机攻击。";
  }
  await chat("<p>🟨 <strong>问号宝箱砖</strong> 顶出（d6=" + d6 + "）：<br>" + line + "</p>");

  // —— 第三次（当天最后一次）风险：用完后掷 1d20，出 1 砖块碎裂 ——
  const block = a.items.find((i) => i.getFlag("world", BLOCK_FLAG));
  if (block && block.system.uses?.value === 0) {
    const d20 = await rollShow("1d20", "💥 砖块耐久");
    if (d20 === 1) {
      await chat("<p>💥 <strong>问号宝箱砖</strong> 发出最后一声哀鸣，<strong>碎裂消散</strong>了……（最后一次使用掷出 1）</p>");
      await block.delete();
    } else {
      await chat("<p>⚠ 今天最后一次使用——砖块剧烈震颤但挺住了（1d20=" + d20 + "，非 1）。</p>");
    }
  }
})();
